AND invited.status = #{query.status}
AND (LOCATE(#{query.keyword}, cycle.cycle_name) > 0 OR LOCATE(#{query.keyword}, objective.objective_name) > 0 OR LOCATE(#{query.keyword}, employee.name) > 0)
ORDER BY invited.invite_time DESC, invited.id DESC

SELECT e.id AS id, e.tenant_id AS tenantId, e.objective_id AS objectiveId, e.assignment_id AS assignmentId, e.result_id AS resultId, e.evaluatee_id AS evaluateeId, e.evaluatee_name AS evaluateeName, e.evaluator_id AS evaluatorId, evaluator_employee.user_id AS evaluatorUserId, e.evaluator_name AS evaluatorName, e.evaluator_source AS evaluatorSource, e.weight AS weight, e.status AS status, e.invite_time AS inviteTime, e.remind_count AS remindCount, r.score AS score, r.dimension_scores AS dimensionScores, r.comment_text AS commentText, r.submit_time AS submitTime FROM hr_perf_evaluator e LEFT JOIN hr_employee evaluator_employee ON evaluator_employee.tenant_id = e.tenant_id AND evaluator_employee.id = e.evaluator_id AND evaluator_employee.deleted = 0 AND e.evaluator_source != 'CUSTOMER' LEFT JOIN hr_perf_evaluator_response r ON r.evaluator_id = e.id AND r.tenant_id = e.tenant_id AND r.deleted = 0 WHERE e.tenant_id = #{tenantId} AND e.deleted = 0 AND e.objective_id = #{objectiveId}
AND e.evaluatee_id = #{evaluateeId}
ORDER BY e.evaluatee_id, e.evaluator_source, e.id
